mapper.select:
SELECT BOARD_ID, BOARD_TYPE, TITLE, ATCH_FILE_GRPID, NOTICE_YN, IMPORTANT_YN, VIEW_CNT, REGIST_DT, REGISTER FROM BOARD WHERE BOARD_TYPE = #{boardType}
AND CONTENT LIKE '%' || #{searchKeyword} || '%'
AND (TITLE LIKE '%' || #{searchKeyword} || '%' OR CONTENT LIKE '%' || #{searchKeyword} || '%')
AND TITLE LIKE '%' || #{searchKeyword} || '%'
ORDER BY NOTICE_YN DESC, IMPORTANT_YN DESC, REGIST_DT DESC, BOARD_ID DESC LIMIT #{recordCountPerPage} OFFSET #{firstIndex}

SELECT BOARD_ID, BOARD_TYPE, TITLE, IMPORTANT_YN, VIEW_CNT, REGIST_DT, REGISTER FROM BOARD WHERE BOARD_TYPE = #{boardType}
AND CONTENT LIKE '%' || #{searchKeyword} || '%'
AND (TITLE LIKE '%' || #{searchKeyword} || '%' OR CONTENT LIKE '%' || #{searchKeyword} || '%')
AND TITLE LIKE '%' || #{searchKeyword} || '%'
AND BOARD_ID < #{cursorId}
ORDER BY BOARD_ID DESC LIMIT #{limit}

mapper.update:
UPDATE BOARD SET TITLE = #{title}, SEARCH_CHOSUNG = #{searchChosung}, CONTENT = #{content}, ATCH_FILE_GRPID = #{atchFileGrpid},
IMPORTANT_YN = #{importantYn},
UPDT_DT = CURRENT_TIMESTAMP, UPDUSR = #{updusr} WHERE BOARD_ID = #{boardId}

UPDATE BOARD
SET VIEW_CNT = COALESCE(VIEW_CNT, 0) + 1
WHERE BOARD_ID = #{boardId}

UPDATE BOARD
SET NOTICE_YN = #{noticeYn},
	UPDT_DT = CURRENT_TIMESTAMP,
	UPDUSR = #{updusr}
WHERE BOARD_ID = #{boardId}
	AND BOARD_TYPE = 'CK'

